tr_\n   170\t\n   171\t\n   172\tdef thai_strftime(\n   173\t    dt_obj: datetime,\n   174\t    fmt: str = \"%-d %b %Y\",\n   175\t    thai_digit: bool = False,\n   176\t    buddhist_era: bool = True,\n   177\t) -> str:\n   178\t    \"\"\"\n   179\t    Convert :class:`datetime.datetime` into Thai date and time format.\n   180\t\n   181\t    The formatting directives are similar to :func:`datatime.strrftime`.\n   182\t\n   183\t    This function uses Thai names and Thai Buddhist Era for these directives:\n   184\t        * **%a** - abbreviated weekday name\n   185\t        (i.e. \"\u0e08\", \"\u0e2d\", \"\u0e1e\", \"\u0e1e\u0e24\", \"\u0e28\", \"\u0e2a\", \"\u0e2d\u0e32\")\n   186\t        * **%A** - full weekday name\n   187\t        (i.e. \"\u0e27\u0e31\u0e19\u0e08\u0e31\u0e19\u0e17\u0e23\u0e4c\", \"\u0e27\u0e31\u0e19\u0e2d\u0e31\u0e07\u0e04\u0e32\u0e23\", \"\u0e27\u0e31\u0e19\u0e40\u0e2a\u0e32\u0e23\u0e4c\", \"\u0e27\u0e31\u0e19\u0e2d\u0e32\u0e17\u0e34\u0e15\u0e22\u0e4c\")\n   188\t        * **%b** - abbreviated month name\n   189\t        (i.e. \"\u0e21.\u0e04.\", \"\u0e01.\u0e1e.\", \"\u0e21\u0e35.\u0e04.\", \"\u0e40\u0e21.\u0e22.\", \"\u0e1e.\u0e04.\", \"\u0e21\u0e34.\u0e22.\", \"\u0e18.\u0e04.\")\n   190\t        * **%B** - full month name\n   191\t        (i.e. \"\u0e21\u0e01\u0e23\u0e32\u0e04\u0e21\", \"\u0e01\u0e38\u0e21\u0e20\u0e32\u0e1e\u0e31\u0e19\u0e18\u0e4c\", \"\u0e1e\u0e24\u0e28\u0e08\u0e34\u0e01\u0e32\u0e22\u0e19\", \"\u0e18\u0e31\u0e19\u0e27\u0e32\u0e04\u0e21\",)\n   192\t        * **%y** - year without century (i.e. \"56\", \"10\")\n   193\t        * **%Y** - year with century (i.e. \"2556\", \"2410\")\n   194\t        * **%c** - date and time representation\n   195\t        (i.e. \"\u0e1e   6 \u0e15.\u0e04. 01:40:00 2519\")\n   196\t        * **%v** - short date representation\n   197\t        (i.e. \" 6-\u0e21.\u0e04.-2562\", \"27-\u0e01.\u0e1e.-2555\")\n   198\t    \"\"\"\n   199\t    thaidate_parts = []\n   200\t\n   201\t    i = 0\n   202\t    fmt_len = len(fmt)\n   203\t    while i < fmt_len:\n   204\t        str_ = \"\"\n   205\t        if fmt[i] == \"%\":\n   206\t            j = i + 1\n   207\t            if j < fmt_len:\n   208\t                fmt_char = fmt[j]\n   209\t                if fmt_char in _NEED_L10N:  # requires localization?\n   210\t                    str_ = _thai_strftime(dt_obj, fmt_char, buddhist_era)\n   211\t                elif fmt_char in _EXTENSIONS:\n   212\t                    fmt_char_ext = fmt_char\n   213\t                    k = j + 1\n   214\t                    if k < fmt_len:\n   215\t                        fmt_char = fmt[k]\n   216\t                        if fmt_char in _NEED_L10N:\n   217\t                            str_ = _thai_strftime(\n   218\t                                dt_obj,\n   219\t                                fmt_char,\n   220\t                                buddhist_era,\n   221\t                            )\n   222\t                        else:\n   223\t                            str_ = _std_strftime(dt_obj, fmt_char)\n   224\t\n   225\t                        if fmt_char_ext == \"-\":\n   226\t                            # GNU libc extension,\n   227\t                            # no padding\n   228\t                            if str_[0] and str_[0] in \" 0\":\n   229\t                                str_ = str_[1:]\n   230\t                        elif fmt_char_ext == \"_\":\n   231\t                            # GNU libc extension,\n   232\t                            # explicitly specify space (\" \") for padding\n   233\t                            if str_[0] and str_[0] == \"0\":\n   234\t                                str_ = \" \" + str_[1:]\n   235\t                        elif fmt_char_ext == \"0\":\n   236\t                            # GNU libc extension,\n   237\t                            # explicitly specify zero (\"0\") for padding\n   238\t                            if str_[0] and str_[0] == \" \":\n   239\t          